#include <iostream>
#include <unordered_map>
#include <string>
using namespace std;

unordered_map<char, char> mirrorMap = {
    {'0','0'}, {'1','1'}, {'2','5'}, {'5','2'}, {'8','8'}
};

bool isValidTime(const string &t) {
    int h = stoi(t.substr(0,2));
    int m = stoi(t.substr(3,2));
    return h < 24 && m < 60;
}

string mirrorTime(const string &t) {
    string combined = t.substr(3,2) + t.substr(0,2);
    string res = "";

    for (int i = combined.size() - 1; i >= 0; i--) {
        if (mirrorMap.find(combined[i]) == mirrorMap.end()) {
            return "";
        }
        res += mirrorMap[combined[i]];
    }

    return res.substr(0,2) + ":" + res.substr(2,2);
}

int main() {
    string time;
    cin >> time;

    int h = stoi(time.substr(0,2));
    int m = stoi(time.substr(3,2));

    for (int total = h * 60 + m; total >= 0; total--) {
        int hh = total / 60;
        int mm = total % 60;

        string candidate =
            (hh < 10 ? "0" : "") + to_string(hh) + ":" +
            (mm < 10 ? "0" : "") + to_string(mm);

        string mirrored = mirrorTime(candidate);

        if (!mirrored.empty() && isValidTime(mirrored)) {
            cout << candidate << endl;
            break;
        }
    }

    return 0;
}

